          <li><strong>Який повсякденний образ пасує?</strong> Позичай звичні слова з простору, світла, дотику чи руху: <em>«тісно»</em>, <em>«тепло»</em>, <em>«поквапливо»</em>, <em>«наче нарешті видихнув»</em>.</li>
