        <li><strong>2. EQ у рожевому шумі (3 рівні):</strong> У <strong>вільному тренуванні</strong> рожевий шум одразу звучить безперервно <strong>з увімкненим підсиленням EQ</strong> (Рівень 1: Широкий EQ <code>+10 дБ / Q 1,6</code>, Рівень 2: Октавний <code>+8,5 дБ / Q 2,6</code>, Рівень 3: Хірургічний <code>+7 дБ / Q 4,2</code>). Плавно перемикайся на чистий шум через верхню картку <strong>Flat</strong> або кнопку <strong>«Байпас Flat»</strong> (<code>Flat: УВІМК.</code>). У режимі <strong>Лише слухати</strong> спочатку коротко звучить нейтральний <em>Flat</em>, далі довший <em>EQ-буст</em> і за кілька секунд відкривається смуга.</li>
