        <li><strong>Фаза 2 — Резонанс і позиція:</strong> М’яке мугикання / вібрація губ (<code>Ммм / Бррр</code>) та низхідні зітхання по квінті (<code>5–4–3–2–1</code>) з’єднують регістри.</li>
