function renderRhythmInstrumentsHTML_UK(filterCat = "all") {
  const list = filterCat === "all"
    ? RHYTHM_INSTRUMENTS_DATA_UK
    : RHYTHM_INSTRUMENTS_DATA_UK.filter(i => i.category === filterCat);

  const ensembleCard = filterCat === "all" ? `
    <div class="article-highlight-box" style="margin-bottom:0.2rem;">
      <h4>Як перкусія ділить один ґрув (частотний розподіл праці):</h4>
      <p style="font-size:0.78rem; color:var(--raccoon-dark); line-height:1.4;">
        Кожен інструмент займає власний поверх частот, щоб у міксі не було каші: <strong>Бочка</strong> тримає низ, <strong>Малий барабан</strong> б’є в пробивній середині, а <strong>Хай-хет і Шейкер</strong> іскряться вгорі.
      </p>
      <div class="k-btn-row" style="margin-top:0.35rem;">
        <button class="btn-tool" data-play-rhythm="band-groove">▶ Ґрув гурту (Бочка + Малий + Хет + Шейкер)</button>
      </div>
    </div>
  ` : "";

  return ensembleCard + list.map(item => `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag ${item.tagClass}">${item.tag}</span>
        <span class="k-ratio-chip">${item.role.split(" (")[0]}</span>
      </div>
      <h4>${item.name}</h4>
      <p><strong>Роль:</strong> ${item.role}</p>
      <p>${item.desc}</p>
      ${item.rhythmKey ? `
        <div class="k-btn-row">
          <button class="btn-tool" data-play-rhythm="${item.rhythmKey}">▶ ${item.btnLabel}</button>
        </div>
      ` : ""}
    </article>
  `).join("");
}

function renderVocalsReferenceHTML_UK() {
  return `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">Людський голос</span>
        <span class="k-ratio-chip">Перший інструмент</span>
      </div>
      <h4>Як людський голос утворює звук</h4>
      <p>Твій голос поєднує три акустичні системи в одному живому інструменті. На відміну від гітари чи флейти, його «корпус» змінює форму за мілісекунди — миттєво керуючи висотою, гучністю, блиском і кожною голосною чи приголосною.</p>

      <div class="physics-fact-grid">
        <div class="physics-fact-item">
          <strong>1. Джерело енергії (Дихання та опора)</strong>
          На вдиху <em>діафрагма</em> плавно опускається, наповнюючи легені. Під час співу м’язи преса й міжребер’я тримають рівний <em>підскладковий тиск</em> («опора»), не затискаючи горло.
        </div>
        <div class="physics-fact-item">
          <strong>2. Вібратор (Гортань і голосові складки)</strong>
          У гортані натягнуті дві еластичні <em>голосові зв’язки</em>. Потік повітря присмоктує і пульсує їх 100–1000 разів на секунду (<em>ефект Бернуллі</em>), народжуючи первинний тон, багатий на обертони.
        </div>
        <div class="physics-fact-item">
          <strong>3. Резонатор (Надставна трубка і форманти)</strong>
          Глотка, ротова порожнина й носоглотка працюють живим фільтром. Рухи язика, щелепи, губ і м’якого піднебіння переміщують піки резонансу — <em>форманти</em>, перетворюючи тепле «У» на яскраве «І».
        </div>
        <div class="physics-fact-item">
          <strong>4. Співоча форманта (~3000 Гц)</strong>
          Розширюючи нижню частину глотки, академічні вокалісти фокусують додаткову енергію близько 2,8–3,2 кГц — саме там, де оркестр звучить тихіше, тому один непідсилений голос перекриває 80 інструментів!
        </div>
      </div>

      <div class="k-btn-row">
        <button class="btn-tool" data-play-inst="true" data-style="choir" data-notes="C4,E4,G4,C5" data-dur="1.9" data-step="0">▶ Послухати хоровий акорд</button>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">Регістри та техніки</span>
        <span class="k-ratio-chip">Вокальні барви</span>
      </div>
      <h4>Вокальні регістри та манери співу</h4>
      <p>Залежно від того, які м’язи гортані працюють і чи вібрує вся товща зв’язок, чи лише їхній тонкий край, голос докорінно змінює забарвлення:</p>

      <div class="physics-fact-grid">
        <div class="physics-fact-item">
          <strong>Грудний голос (Модальний регістр, M1)</strong>
          Коливається вся м’язова маса зв’язок. Дає соковитий, теплий, насичений обертонами звук — наш природний розмовний тембр і міцна база низу й середини.
        </div>
        <div class="physics-fact-item">
          <strong>Головний голос і фальцет (M2)</strong>
          Зв’язки видовжуються й тоншають, тож вібрують переважно їхні ніжні краї. Звучання стає легким, польотним і флейтовим (зв’язний академічний головний регістр або повітряний <em>фальцет</em>).
        </div>
        <div class="physics-fact-item">
          <strong>Мікст (Mixed Voice / Voix mixte)</strong>
          Плавний місток через перехідні ноти (<em>пассаджо</em>). Збалансована координація м’язів поєднує силу грудного голосу з легкістю верхів без різкого зламу.
        </div>
        <div class="physics-fact-item">
          <strong>Белтинг (Поп, мюзикл, госпел)</strong>
          Піднімає щільну грудну опору високо вгору завдяки потужному диханню та яскравим голосним — сміливий, прямий звук аж до G5/C6.
        </div>
        <div class="physics-fact-item">
          <strong>Вібрато</strong>
          Природна розслаблена періодична пульсація висоти й гучності близько 5–7 Гц. Додає тепла тягнучим нотам і виділяє сольний голос над ансамблем.
        </div>
        <div class="physics-fact-item">
          <strong>Скет і обертоновий спів</strong>
          Джазовий <em>скет</em> імітує духові соло ритмічними складами. А в <em>горловому / обертоновому співі</em> точне положення язика підсилює окремий обертон над бурдоном, і один співак видобуває два звуки водночас!
        </div>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">Хоровий склад (SATB)</span>
        <span class="k-ratio-chip">Партії й діапазони</span>
      </div>
      <h4>Всередині хору: чотири партії SATB і діапазони</h4>
      <p>Мішані хори всього світу будуються за схемою <strong>SATB</strong> — зверху донизу за назвами чотирьох партій. Великі симфонічні хори часто ділять кожну партію на перші (вищі) й другі (нижчі) голоси: <em>SSAATTBB</em>.</p>

      <div class="physics-fact-grid">
        <div class="physics-fact-item">
          <strong>Сопрано (S) • Діапазон C4–C6</strong>
          Найвищий жіночий або дискантовий голос. Зазвичай веде головну мелодію, верхні підголоски та кришталеве сяйво акорду.
        </div>
        <div class="physics-fact-item">
          <strong>Альт (A) • Діапазон F3–E5</strong>
          Низький жіночий голос (або партія контратенора). Наповнює внутрішнє тепло гармонії — терції, септими й м’які підголоски одразу під мелодією.
        </div>
        <div class="physics-fact-item">
          <strong>Тенор (T) • Діапазон C3–A4</strong>
          Високий чоловічий голос (у нотах зазвичай записується в скрипковому ключі на октаву вище реального звучання!). Поєднує верх і низ ліричними лініями.
        </div>
        <div class="physics-fact-item">
          <strong>Бас (B) • Діапазон E2–E4</strong>
          Найглибший чоловічий голос і акустичний якір хору. Нота баса задає фундамент гармонії — коли баси тримають чистий стрій, увесь акорд стає як влитий.
        </div>
        <div class="physics-fact-item">
          <strong>Мецо-сопрано, баритон і контратенор</strong>
          Три важливі проміжні голоси: <em>Мецо</em> (A3–A5, теплий міст між сопрано й альтом), <em>Баритон</em> (G2–G4, найпоширеніший чоловічий тембр) та <em>Контратенор</em> (чоловічий альт у розвиненому головному резонансі).
        </div>
        <div class="physics-fact-item">
          <strong>Інші хорові склади</strong>
          <em>Однорідні жіночі/дитячі хори (SSAA)</em> та <em>чоловічі ансамблі (TTBB / барбершоп)</em> творять тісні переливчасті співзвуччя. Сучасні <em>акапельні</em> гурти додають вокальну перкусію (бітбокс) замість ударних.
        </div>
      </div>

      <div class="k-btn-row">
        <button class="btn-tool" data-play-inst="true" data-style="choir" data-notes="G4,B4,D5,G5" data-dur="0.95" data-step="320">▶ Діапазон сопрано</button>
        <button class="btn-tool" data-play-inst="true" data-style="choir" data-notes="G3,Bb3,D4,F4" data-dur="0.95" data-step="320">▶ Діапазон альта</button>
        <button class="btn-tool" data-play-inst="true" data-style="choir" data-notes="C3,E3,G3,B3" data-dur="0.95" data-step="320">▶ Діапазон тенора</button>
        <button class="btn-tool" data-play-inst="true" data-style="choir" data-notes="E2,G2,B2,E3" data-dur="1.05" data-step="340">▶ Фундамент баса</button>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">Інтонація й слух</span>
        <span class="k-ratio-chip">Чистий стрій</span>
      </div>
      <h4>Чому хор a cappella може звучати чистіше за рояль</h4>
      <p>Фортепіано настроєне у <strong>12-ступеневій рівномірній темперації</strong>: його велика терція звучить на 14 центів вище за ідеал, щоб можна було вільно грати в усіх 12 тональностях. Вокалісти не скуті фіксованими ладами чи молоточками.</p>
      <p>Співаючи без супроводу, добрий хор інстинктивно підлаштовується в абсолютно чисті <strong>натуральні пропорції частот</strong> (2:1 октава, 3:2 квінта, 5:4 велика терція). Щойно велика терція сходиться без жодного биття, спільні обертони підсилюються — і акорд раптом розквітає дзвінкіше й об’ємніше (ефект «барбершоп-обертону»).</p>
      <div class="k-btn-row">
        <button class="btn-tool" data-play-inst="true" data-style="choir" data-notes="C3,G3,E4,C5" data-dur="1.4" data-step="460">▶ Побудувати по голосах (Бас → Сопрано)</button>
        <button class="btn-tool" data-play-inst="true" data-style="choir" data-notes="C3,G3,E4,C5" data-dur="2.4" data-step="0">▶ Повний акорд хору SATB</button>
        <button class="btn-tool" data-open-warmup="true">▶ Відкрити 5-хв розспівку</button>
      </div>
    </article>
  `;
}

