function renderModesReferenceHTML_UK(familyFilter = "all") {
  const list = familyFilter === "all"
    ? MODES_ENCYCLOPEDIA_UK
    : MODES_ENCYCLOPEDIA_UK.filter(m => m.family === familyFilter);

  return `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">Головний принцип</span>
        <span class="k-ratio-chip">Відносний vs. паралельний</span>
      </div>
      <h4>Що таке лади (церковні модуси)?</h4>
      <p>
        <strong>Лад</strong> виникає, коли ти береш точно той самий набір нот, але призначаєш центром тяжіння (<strong>тонікою</strong>) інший звук. На самих лише білих клавішах (нотах до мажору) кожна нова стартова клавіша дає інший візерунок тонів і півтонів: почни від <code>D</code> — вийде <em>дорійський</em>, від <code>E</code> — <em>фригійський</em>, від <code>F</code> — <em>лідійський</em>, від <code>G</code> — <em>міксолідійський</em>, від <code>A</code> — <em>еолійський</em>, від <code>B</code> — <em>локрійський</em>.
      </p>
      <div class="k-compare-grid">
        <div class="k-compare-box is-sage">
          <h5>1. Відносний погляд (Ті самі клавіші)</h5>
          <p>Зручно для орієнтації на клавіатурі: «Ре дорійський має ті самі білі клавіші, що й До мажор». Проте на слух спершу підступно, бо вухо ще тягне до До як до дому.</p>
        </div>
        <div class="k-compare-box is-peach">
          <h5>2. Паралельний погляд (Спільна тоніка!)</h5>
          <p><strong>Ключ для розвитку слуху:</strong> грай усі 7 ладів від ноти <code>C</code>! Тоді єдина характерна нота миттєво видає настрій (напр. <code>C → F#</code> = лідійський, <code>C → Bb</code> = міксолідійський).</p>
        </div>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">Спектр яскравості ладів</span>
        <span class="k-ratio-chip">Світлий → темний</span>
      </div>
      <h4>Упорядковано за світлом (удовж кварто-квінтового кола)</h4>
      <p>
        Розташуй 7 ладів від найсяйнішого до найтемнішого замість порядку ступенів 1–7 — і кожен крок опускатиме рівно <strong>одну ноту на півтон</strong>, точно повторюючи рух кварто-квінтовим колом:
      </p>
      <div class="mode-spectrum-strip">
        <span class="mode-spec-chip is-bright">1. Лідійський (#4)</span>
        <span class="mode-spec-chip">2. Іонійський</span>
        <span class="mode-spec-chip">3. Міксолідійський (b7)</span>
        <span class="mode-spec-chip">4. Дорійський (b3, b7)</span>
        <span class="mode-spec-chip">5. Еолійський (+b6)</span>
        <span class="mode-spec-chip">6. Фригійський (+b2)</span>
        <span class="mode-spec-chip is-dark">7. Локрійський (+b5)</span>
      </div>
    </article>

    <div class="k-filter-row" aria-label="Фільтрувати лади">
      <button class="k-filter-pill ${familyFilter === "all" ? "active" : ""}" data-mfilter="all">Усі (9)</button>
      <button class="k-filter-pill ${familyFilter === "major" ? "active" : ""}" data-mfilter="major">Мажорні (3)</button>
      <button class="k-filter-pill ${familyFilter === "minor" ? "active" : ""}" data-mfilter="minor">Мінорні (4)</button>
      <button class="k-filter-pill ${familyFilter === "variant" ? "active" : ""}" data-mfilter="variant">Варіанти мінору (2)</button>
    </div>

    <div class="knowledge-list">
      ${list.map(m => `
        <article class="knowledge-card">
          <div class="k-card-top-row">
            <span class="k-card-tag ${m.family === "major" ? "tag-peach" : m.family === "variant" ? "tag-sage" : "tag-lilac"}">${m.familyLabel} • ${m.brightness}</span>
            <span class="k-ratio-chip">${m.formula}</span>
          </div>
          <h4>${m.name} (приклад від ${m.rootLabel})</h4>
          <p class="k-char">${m.stammton}</p>
          <p><strong>Барвиста нота:</strong> ${m.charNote}<br><strong>Будова тонів (Т/П):</strong> <code>${m.steps}</code></p>
          <p>${m.desc}</p>
          <p>${m.usage}</p>
          <div class="k-btn-row">
            <button class="btn-tool" data-play-mode-scale="${m.id}">▶ Гама (${m.rootLabel})</button>
            <button class="btn-tool" data-play-mode-vamp="${m.id}">▶ Вамп: ${m.vamp}</button>
          </div>
        </article>
      `).join("")}
    </div>
  `;
}

