function renderKeysReferenceHTML_UK(circleFilter = "all") {
  const list = circleFilter === "all"
    ? KEYS_CIRCLE_DATA_UK
    : KEYS_CIRCLE_DATA_UK.filter(k => k.group === circleFilter);

  return `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">1. Головна ідея</span>
        <span class="k-ratio-chip">Тональність і знаки при ключі</span>
      </div>
      <h4>Гама vs. тональність: що насправді творить тональність?</h4>
      <p>
        <strong>Гама</strong> — це просто звуки по порядку висоти (напр. C–D–E–F–G–A–B–C). <strong>Тональність</strong> описує всю <em>систему магнітного тяжіння</em> довкола головного тону: вона визначає центр спокою (<strong>Тоніку</strong>), нахил (ясний <strong>мажор</strong> або глибокий <strong>мінор</strong>) і те, які звуки постійно підвищені (♯) чи понижені (♭) за допомогою <strong>ключових знаків</strong>.
      </p>
      <div class="physics-fact-grid">
        <div class="physics-fact-item">
          <strong>Навіщо потрібні ключові знаки?</strong>
          Кожен мажор вимагає однакової формули кроків: <code>Т – Т – П – Т – Т – Т – П</code> (півтони між III–IV і VII–VIII). Перенеси гаму з До в <code>Соль (G)</code> — і VII ступінь (<code>F</code>) опиниться занизько, тож його підіймають до <code>F#</code> заради правильного ввідного тону.
        </div>
        <div class="physics-fact-item">
          <strong>Ключові знаки проти випадкових</strong>
          <strong>Ключові знаки</strong> стоять одразу біля ключа й діють на весь твір (у всіх октавах). <strong>Випадковий знак</strong> (біля окремої ноти в такті) діє лише до найближчої тактової риски для тимчасової барви.
        </div>
      </div>
    </article>

    <div class="k-sibling-bar">
      <span><strong>Досліджуй візуально й на слух:</strong> Відкрий інтерактивне Кварто-квінтове коло з живими акордами та модуляціями.</span>
      <button type="button" class="btn-tool" data-jump-ref="circle-of-fifths">Відкрити Кварто-квінтове коло →</button>
    </div>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">2. Логіка кварто-квінтового кола</span>
        <span class="k-ratio-chip">3:2 → 12 центрів</span>
      </div>
      <h4>Чому всі 12 тональностей складаються в чіткий циферблат</h4>
      <p>
        Одразу після октави (2:1) найтіснішою спорідненістю є <strong>чиста квінта (3:2)</strong>. Рухайся за годинниковою стрілкою вгору по квінтах (<code>C → G → D → A → E → B → F#</code>) — кожен крок додає один <strong>дієз (♯)</strong>. Рухайся проти стрілки вгору по квартах (<code>C → F → Bb → Eb → Ab → Db → Gb</code>) — щокроку додається <strong>бемоль (♭)</strong>.
      </p>
      <div class="k-compare-grid">
        <div class="k-compare-box is-peach">
          <h5>За стрілкою: дієзні тональності (♯)</h5>
          <p><strong>Мажорні:</strong> <em>G, D, A, E, B, F#</em>.<br><strong>Порядок дієзів:</strong> <code>Фа♯ – До♯ – Соль♯ – Ре♯ – Ля♯ – Мі♯</code> (кожен новий дієз — це завжди VII ввідний ступінь нової тональності!).</p>
        </div>
        <div class="k-compare-box is-lilac">
          <h5>Проти стрілки: бемольні тональності (♭)</h5>
          <p><strong>Мажорні:</strong> <em>F, Bb, Eb, Ab, Db, Gb</em>.<br><strong>Порядок бемолів:</strong> <code>Сі♭ – Мі♭ – Ля♭ – Ре♭ – Соль♭ – До♭</code> (дзеркально назад!). Лайфхак: <strong>передостанній бемоль</strong> називає мажорну тоніку.</p>
        </div>
      </div>
      <p class="k-tip"><strong>Піфагорова кома та енгармонізм:</strong> 12 чистих квінт 3:2 перевищують 7 октав на ~23,5 цента (<em>піфагорова кома</em>). Сучасна <strong>рівномірна темперація</strong> рівно ділить цю різницю між усіма кроками, тож <code>Фа♯ мажор</code> (6♯) та <code>Соль♭ мажор</code> (6♭) сходяться на абсолютно тих самих клавішах.</p>
    </article>

    <div class="section-heading-row">
      <h2 class="section-heading">3. Повний атлас 12 тональностей</h2>
    </div>

    <div class="k-filter-row" aria-label="Фільтрувати тональності за знаками">
      <button class="k-filter-pill ${circleFilter === "all" ? "active" : ""}" data-kfilter="all">Усі 12 тональностей</button>
      <button class="k-filter-pill ${circleFilter === "neutral" ? "active" : ""}" data-kfilter="neutral">C / Am (0 знаків)</button>
      <button class="k-filter-pill ${circleFilter === "sharp" ? "active" : ""}" data-kfilter="sharp">Дієзи (♯)</button>
      <button class="k-filter-pill ${circleFilter === "flat" ? "active" : ""}" data-kfilter="flat">Бемолі (♭)</button>
    </div>

    <div class="knowledge-list">
      ${list.map(k => `
        <article class="knowledge-card">
          <div class="k-card-top-row">
            <span class="k-card-tag ${k.group === "sharp" ? "tag-peach" : k.group === "flat" ? "tag-lilac" : "tag-sage"}">${k.sigBadge}</span>
            <span class="k-ratio-chip">${k.majorName} / ${k.minorName}</span>
          </div>
          <h4>${k.majorName} і паралельний ${k.minorName}</h4>
          <p><strong>Знаки при ключі:</strong> ${k.accidentalList}</p>
          <p><strong>Діатонічні тризвуки:</strong> <code>${k.chords}</code></p>
          <p class="k-tip">${k.instrumentTip}</p>
          <div class="k-btn-row">
            <button class="btn-tool" data-play-key-cadence="${k.rootMidi}" data-key-mode="major">▶ Каданс ${k.majorName}</button>
            <button class="btn-tool" data-play-key-cadence="${k.minorMidi}" data-key-mode="minor">▶ ${k.minorName}</button>
          </div>
        </article>
      `).join("")}
    </div>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">4. Три види мінору</span>
        <span class="k-ratio-chip">Чому в мінору 3 гами</span>
      </div>
      <h4>Натуральний, гармонічний і мелодичний мінор (на прикладі ля мінору)</h4>
      <p>
        Мажор обходиться однією формою, а мінор використовує аж три, бо в натуральному мінорі немає гострого півтонового ввідного тону до тоніки (<code>G → A</code> — цілий тон, тяжіє м’яко, а не як півтон <code>G# → A</code>):
      </p>
      <ul class="k-physics-list">
        <li><strong>Натуральний мінор (еолійський):</strong> Бере рівно ті самі знаки, що й паралельний мажор (<code>A–B–C–D–E–F–G–A</code>). Природний, народний, прозорий.</li>
        <li><strong>Гармонічний мінор:</strong> Підвищує VII ступінь (<code>G → G#</code>), щоб акорд V став виразною <strong>мажорною домінантою (E7)</strong>. Водночас між <code>F</code> і <code>G#</code> виникає екзотичний стрибок у 3 півтони.</li>
        <li><strong>Мелодичний мінор:</strong> Згладжує цей стрибок для плавного співу й басових ліній, підвищуючи в русі вгору також і VI ступінь (<code>F → F#, G → G#</code>); у класиці при спуску повертається до натурального, а в джазі звучить незмінно вгору й униз.</li>
      </ul>
      <div class="k-btn-row">
        <button class="btn-tool" data-play-inst="true" data-style="piano" data-notes="A3,B3,C4,D4,E4,F4,G4,A4" data-dur="0.45" data-step="320">▶ Натуральний ля мінор</button>
        <button class="btn-tool" data-play-inst="true" data-style="piano" data-notes="A3,B3,C4,D4,E4,F4,G#4,A4" data-dur="0.45" data-step="320">▶ Гармонічний ля мінор</button>
        <button class="btn-tool" data-play-inst="true" data-style="piano" data-notes="A3,B3,C4,D4,E4,F#4,G#4,A4" data-dur="0.45" data-step="320">▶ Мелодичний ля мінор</button>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">5. Спорідненість тональностей і модуляції</span>
        <span class="k-ratio-chip">Зміна центру</span>
      </div>
      <h4>Як тональності поєднуються й плавно переходять одна в одну</h4>
      <div class="physics-fact-grid">
        <div class="physics-fact-item">
          <strong>Паралельні тональності (різниця в малу терцію)</strong>
          Мають абсолютно спільний набір звуків і знаків: <code>До мажор ↔ Ля мінор</code>, <code>Соль мажор ↔ Мі мінор</code>. Зміна опори звучить природно й непомітно.
        </div>
        <div class="physics-fact-item">
          <strong>Однойменні тональності (спільна тоніка)</strong>
          Тримають той самий основний тон, змінюючи мажор на мінор чи навпаки: <code>До мажор ↔ До мінор</code> (різниця в 3 бемолі!). Дають потужні контрасти на кшталт світлої «пікардійської терції».
        </div>
        <div class="physics-fact-item">
          <strong>Близьке споріднення (сусіди по колу)</strong>
          Сусіди на один крок ліворуч чи праворуч (<code>C ↔ G</code> або <code>F</code>) різняться всього одним звуком. Спільні акорди (як <code>Am</code>) стають плавним містком модуляції.
        </div>
        <div class="physics-fact-item">
          <strong>Медіанти та зсув на півтон/тон</strong>
          Стрибок на терцію (<code>C → Ab</code> або <code>E</code>) миттєво оновлює фарби для кінематографічного ефекту — а прямий підйом на півтон чи тон у фінальному приспіві додає вибуху енергії.
        </div>
      </div>
      <div class="k-btn-row">
        <button class="btn-tool" data-play-custom="key-variant">▶ Однойменні C ↔ Cm</button>
        <button class="btn-tool" data-play-custom="key-mediant">▶ Медіантний зсув C → Ab → C</button>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">6. Транспонуючі інструменти й характер</span>
        <span class="k-ratio-chip">Практика в оркестрі</span>
      </div>
      <h4>Чому в духових у партитурі інші ключові знаки, ніж у фортепіано</h4>
      <p>
        Поки фортепіано, гітара, струнні та флейта читають ноти в <strong>незмінному строї (у C)</strong>, багато духових інструментів транспонуються, щоб аплікатура пальців лишалася однаковою на великих і малих різновидах інструмента:
      </p>
      <ul class="k-physics-list">
        <li><strong>Інструменти в Bb (труба, кларнет, тенор-саксофон):</strong> Написана <code>C</code> реально звучить як <code>Bb</code> (на велику секунду нижче). Коли гурт грає в <code>Bb мажорі (2♭)</code>, труба читає чистий <code>До мажор (0 знаків)</code>!</li>
        <li><strong>Інструменти в Eb (альт-саксофон, баритон-саксофон):</strong> Написана <code>C</code> звучить як <code>Eb</code> (на велику сексту нижче). Коли ансамбль у <code>Eb мажорі (3♭)</code>, альт-сакс вільно грає по білих нотах <code>C</code>.</li>
        <li><strong>Інструменти в F (валторна, англійський ріжок):</strong> Написана <code>C</code> звучить на чисту квінту нижче, як <code>F</code>.</li>
      </ul>
      <p class="k-tip"><strong>«Характер» тональності:</strong> До появи рівномірної темперації нерівні інтервали дарували кожній тональності унікальний присмак (м’який <em>Ре♭</em>, святковий <em>Ре</em>). Сьогодні математика в усіх 12 однакова — та живі інструменти все одно забарвлюють кожну тональність відкритими струнами, акустикою розтрубів і вокальною теситурою.</p>
    </article>
  `;
}

function renderSingAndPlayReferenceHTML_UK() {
  return `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">1. Чому збивається координація</span>
        <span class="k-ratio-chip">Автопілот і фокус</span>
      </div>
      <h4>Чому грати й співати одночасно спершу так непросто</h4>
      <p>
        Щойно ти граєш і співаєш водночас, дві абсолютно різні системи ділять той самий час: <strong>руки</strong> (моторна пам’ять, аплікатури, бій) і <strong>голос</strong> (дихання, інтонація, текст). Оперативна пам’ять просто не може в ручному режимі керувати двома <em>новими</em> завданнями одночасно.
      </p>
      <div class="physics-fact-grid">
        <div class="physics-fact-item">
          <strong>Постав бодай руки на автопілот</strong>
          Коли голос і руки заважають одне одному, мозок усе ще контролює обидва процеси вручну. Рішення: доведи акомпанемент (або вокал) до автоматизму, як підйом сходами.
        </div>
        <div class="physics-fact-item">
          <strong>Закріпи ритм раніше за ноти</strong>
          90% затисків стаються через ритм, а не через фальшиві ноти! Коли склад тексту падає між ударами чи натисканням клавіш, рука зупиняється — доки обидва ритми не зв’язані чітко.
        </div>
        <div class="physics-fact-item">
          <strong>Мугикай на «Ла» або «Ду» спершу</strong>
          Згадування слів забирає величезну частку уваги. Наспівавши мелодію на один нейтральний склад, ти звільняєш мозок для точного строю й ґруву.
        </div>
        <div class="physics-fact-item">
          <strong>Один спільний внутрішній метроном</strong>
          Дозволь легкому притупуванню ногою бути головним — голос не наздоганяє руку, а рука не чекає на голос: <em>обидва</em> прив’язані до спільного пульсу.
        </div>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">2. Ефективний план у 5 кроків</span>
        <span class="k-ratio-chip">Покроковий метод</span>
      </div>
      <h4>Перевірена рутина з 5 кроків для будь-якої пісні</h4>
      <p>
        Замість того щоб щоразу починати спочатку й збиватися на тому самому куплеті, розділи координацію на п’ять прицільних етапів:
      </p>
      <ul class="article-steps-list">
        <li>
          <strong>1. Розмовний тест (автоматизуй руки):</strong> Зацикли акорди чи ритмічний бій на 1–2 хвилини й спробуй одночасно рахувати вголос до 20 або вільно підтримувати розмову. Якщо руки спотикаються — приділи інструменту ще 5 хвилин соло.
        </li>
        <li>
          <strong>2. Промовляй текст суворо в ритм:</strong> Грай акомпанемент і <strong>чітко проговорюй слова в ритмі</strong> пісні без мелодії (на одній зручній ноті). Без мелодії ти миттєво відчуєш, які склади падають у долю, а які між ударами.
        </li>
        <li>
          <strong>3. Розстав фізичні якорі:</strong> Познач точні точки зустрічі: <em>«Бас у лівій руці вдаряє рівно на слово “ніч”»</em> або <em>«“вітер” заходить на рух медіатором угору між 2 і 3»</em>. Мозок блискавично координується довкола конкретних точок!
        </li>
        <li>
          <strong>4. Спрости акомпанемент і зацикли 1–2 такти:</strong> Спершу бери рівно <strong>один удар на раз</strong> і спокійно співай поверх. Потім додай третю долю, і лише згодом повертай повний бій чи перебір — завжди у коротких петлях по 1–2 такти!
        </li>
        <li>
          <strong>5. Сповільнення (60%) і «уявний спів»:</strong> Зменш темп майже вдвічі. На хитрих вступах із затакту проспівай мелодію подумки беззвучно під акомпанемент, потім тихо промугикай, і вже тоді співай повним голосом.
        </li>
      </ul>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">3. Щоденні вправи на незалежність</span>
        <span class="k-ratio-chip">Спробуй просто зараз</span>
      </div>
      <h4>6 прицільних вправ на координацію голосу й рук</h4>
      <p>
        Усього 5–8 хвилин на одну-дві з цих вправ перед розбором пісень дають свободу в рази швидше за механічне повторення:
      </p>
      <ul class="k-physics-list">
        <li>
          <strong>Вправа 1 — Перевірка розмовою й рахунком:</strong> Грай рівну послідовність із чотирьох акордів (<code>I – V – vi – IV</code>) ритмічним боєм або на піано й водночас читай абзац уголос чи рахуй назад від 20 до 1. Правило: ґрув не має здригнутися ні на міліметр.
        </li>
        <li>
          <strong>Вправа 2 — Якір на сильну долю:</strong> Бери кожен акорд один раз на першу долю такту (тягнучи цілу ноту) й співай увесь куплет над відкритим дзвоном. Тренує фразування, дихання й чисту зміну акордів без метушні.
        </li>
        <li>
          <strong>Вправа 3 — Інтонування над педальним бурдоном:</strong> Тримай на інструменті відкриту квінту-основу (<code>C3 + G3</code>) й співай над нею мелодії або інтервали. Ідеально відокремлює слух і голос від зайвої метушні лівої руки.
        </li>
        <li>
          <strong>Вправа 4 — Синкопи й пастка «4-і»:</strong> У поп- і соул-вокалі фраза часто починається на півдолі <em>раніше</em> (на <code>4-і</code>), поки гітара чи піано переходить на акорд чітко на 1-шу долю. Відстукуй рівні чверті, запускаючи вокал на «і».
        </li>
        <li>
          <strong>Вправа 5 — Рухомий бас проти тягнучої ноти:</strong> Веди просту басову лінію (напр. <code>C – F – G – C</code>), поки голос тримає одну спільну ноту (<code>G</code>) — або навпаки: тримай один статичний акорд і плавно проспівуй гами вгору й униз.
        </li>
        <li>
          <strong>Вправа 6 — 20-секундний запис на телефон:</strong> Запиши один короткий уривок на диктофон і одразу прослухай. Погляд збоку миттєво покаже непомітні випадіння долей чи прискорення.
        </li>
      </ul>
      <div class="k-btn-row">
        <button class="btn-tool" data-play-progression="I,V,vi,IV">▶ Вправа 1: Ґрув для розмови</button>
        <button class="btn-tool" data-play-custom="sp-drone">▶ Вправа 3: Бурдон + мелодія</button>
        <button class="btn-tool" data-play-custom="sp-syncopation">▶ Вправа 4: Пульс проти затакту</button>
        <button class="btn-tool" data-play-custom="sp-poly">▶ Вправа 5: Рухомий бас, нерухомий тон</button>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">4. Поради для інструментів і типові пастки</span>
        <span class="k-ratio-chip">Гітара, фортепіано й голос</span>
      </div>
      <h4>Секрети, що заощаджують тижні зайвих спроб</h4>
      <div class="physics-fact-grid">
        <div class="physics-fact-item">
          <strong>Гітара: не зупиняй маятник правої руки</strong>
          Твоя права рука — неперервний метроном (<em>Вниз – Угору – Вниз – Угору</em>). Навіть на паузах і синкопованому вокалі не гальмуй рух — просто проводь рукою над струнами в повітрі.
        </div>
        <div class="physics-fact-item">
          <strong>Фортепіано: додавай ритми по шарах</strong>
          Почни виключно з <em>баса лівою рукою на раз + спів</em>. Потім додай спокійні тризвуки правою на 1 і 3. Рухливі восьмі чи підголоски включаються лише наприкінці.
        </div>
        <div class="physics-fact-item">
          <strong>Сміливо транспонуй під голос</strong>
          Напруження на незручних верхніх нотах миттєво руйнує координацію рук. Не вагайся поставити <strong>каподастр</strong> або змістити тональність на ±2 півтони, щоб голос лився легко.
        </div>
        <div class="physics-fact-item">
          <strong>Плануй вдихи як ноти в такті</strong>
          Збої найчастіше трапляються не посеред фрази, а на переході між рядками! Забронюй одну чвертну паузу для спокійного вдиху перед приспівом, доки інструмент рівно веде вперед.
        </div>
      </div>
      <p class="k-tip"><strong>Бонус-порада від Lauscher:</strong> У модулях <strong>Сольфеджіо</strong> та <strong>Мелодії</strong> спробуй спершу тихо проспівати цільову ноту вголос <em>перед тим</em>, як натиснути клавішу — це з’єднує слух, голос і пальці в єдиний рефлекс.</p>
    </article>
  `;
}

function renderCircleOfFifthsTheoryHTML_UK() {
  return `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">1. Головна ідея</span>
        <span class="k-ratio-chip">Квінта 3:2 • 12 тональностей</span>
      </div>
      <h4>Що таке Кварто-квінтове коло — і чому воно замикається?</h4>
      <p>
        Одразу після октави (<code>2:1</code>) <strong>чиста квінта (3:2)</strong> — найміцніший акустичний зв’язок у музиці. Якщо підніматися квінтами від <strong>C</strong> (<code>C → G → D → A → E → B → F♯…</code>), на кожному кроці підвищується рівно одна нота для нового ввідного тону — за годинниковою стрілкою додається по <strong>одному дієзу (♯)</strong>. А рух проти стрілки (квінти вниз або <strong>кварти вгору</strong>: <code>C → F → B♭ → E♭ → A♭ → D♭ → G♭</code>) м’яко знімає яскравість і додає по <strong>одному бемолю (♭)</strong>.
      </p>
      <p>
        Через 12 кроків рівномірна темперація безшовно замикає коло в точці <strong>6 годин (F♯ / G♭)</strong>, де 6 дієзів і 6 бемолів звучать на абсолютно тих самих клавішах (<strong>енгармонізм</strong>). Замість зубріння 12 розрізнених гам ти отримуєш єдиний музичний компас!
      </p>
      <div class="k-compare-grid">
        <div class="k-compare-box is-peach">
          <h5>За стрілкою (+1 ♯) • Квінти вгору</h5>
          <p><code>C → G → D → A → E → B → F♯</code><br>Звучання крок за кроком світлішає. Порядок дієзів: <code>Фа♯ – До♯ – Соль♯ – Ре♯ – Ля♯ – Мі♯</code>.</p>
        </div>
        <div class="k-compare-box is-lilac">
          <h5>Проти стрілки (+1 ♭) • Кварти вгору</h5>
          <p><code>C → F → B♭ → E♭ → A♭ → D♭ → G♭</code><br>Барва теплішає і пом’якшується. Порядок бемолів іде рівно навпаки: <code>Сі♭ – Мі♭ – Ля♭ – Ре♭ – Соль♭ – До♭</code>.</p>
        </div>
      </div>
    </article>

    <details class="knowledge-card k-accordion">
      <summary class="k-accordion-summary">
        <div class="k-accordion-head">
          <div class="k-card-top-row">
            <span class="k-card-tag tag-peach">2. Як користуватися</span>
            <span class="k-ratio-chip">Логіка циферблата</span>
          </div>
          <h4>Як читати Кварто-квінтове коло за 20 секунд</h4>
        </div>
        <span class="k-accordion-chevron" aria-hidden="true">⌄</span>
      </summary>
      <div class="k-accordion-body">
        <ul class="k-physics-list">
          <li><strong>Зовнішнє кільце = Мажор, Внутрішнє кільце = Паралельний мінор:</strong> Кожен сектор поєднує мажорну тональність із її <strong>паралельним мінором</strong> прямо під нею (<code>C / Am</code>, <code>G / Em</code>, <code>D / Bm</code>…). Вони ділять <em>точно ті самі 7 нот і ключові знаки</em> — мінор просто спирається на VI ступінь (3 півтони нижче).</li>
          <li><strong>Трюк на 1 секунду для дієзів:</strong> Подивись на <em>останній дієз</em> при ключі й піднімися на <strong>півтон угору</strong> — це й буде мажорна тоніка! (напр., 2 дієзи <code>F♯, C♯</code> → півтон вище <code>C♯</code> = <strong>Ре мажор / D</strong>).</li>
          <li><strong>Трюк на 1 секунду для бемолів:</strong> <em>Передостанній бемоль</em> при ключі прямо називає мажорну тональність! (напр., 3 бемолі <code>B♭, E♭, A♭</code> → передостанній = <strong>Мі♭ мажор / Eb</strong>; лише <code>1♭ = Фа мажор / F</code> запам’ятовується окремо).</li>
          <li><strong>Читай Ліво – Центр – Право як дорожню карту:</strong> Обраний сектор — це дім <code>I</code>. Сусід ліворуч — завжди <strong>Субдомінанта (IV)</strong>, а сусід праворуч — завжди <strong>Домінанта (V)</strong>!</li>
        </ul>
      </div>
    </details>

    <details class="knowledge-card k-accordion">
      <summary class="k-accordion-summary">
        <div class="k-accordion-head">
          <div class="k-card-top-row">
            <span class="k-card-tag tag-lilac">3. Чому це суперсила</span>
            <span class="k-ratio-chip">Реальна користь у грі</span>
          </div>
          <h4>Що миттєво покращується, коли знаєш Коло?</h4>
        </div>
        <span class="k-accordion-chevron" aria-hidden="true">⌄</span>
      </summary>
      <div class="k-accordion-body">
        <div class="physics-fact-grid">
          <div class="physics-fact-item">
            <strong>1. Готова карта акордів для джемів і пісень</strong>
            Поглянь на підсвічений 3-секторний клин угорі: твоя тоніка плюс лівий і правий сусіди дають <strong>усі 6 головних діатонічних акордів</strong> тональності (<code>IV – I – V</code> зовні + <code>ii – vi – iii</code> всередині)! Тисячі поп-, рок- та фолк-хітів тримаються виключно в цьому секторі.
          </div>
          <div class="physics-fact-item">
            <strong>2. Миттєве транспонування й каподастр</strong>
            Зависоко співати? Просто посунь увесь блок із 3 секторів за чи проти стрілки кола — усі пропорції лишаться незмінними (<code>I–V–vi–IV</code> у C переїжджає в <code>G–D–Em–C</code> або <code>F–C–Dm–B♭</code>).
          </div>
          <div class="physics-fact-item">
            <strong>3. Плавні й драматичні модуляції</strong>
            Сусідні сектори відрізняються <strong>усього однією нотою</strong> (6 спільних із 7!), тому зміна тональності в бріджі звучить природно. Стрибок через усе коло (6 кроків / тритоновий полюс) змінює майже всі звуки — ідеально для кіноконтрасту.
          </div>
          <div class="physics-fact-item">
            <strong>4. Швидше підбирання на слух і читання</strong>
            Помітив, що культова джазова й поп-секвенція (<code>iii – vi – ii – V – I</code>) крокує по колу <em>проти годинникової стрілки</em> сектор за сектором? Твоє вухо починає передбачати рух баса геометрично, а не навмання.
          </div>
        </div>
      </div>
    </details>

    <details class="knowledge-card k-accordion">
      <summary class="k-accordion-summary">
        <div class="k-accordion-head">
          <div class="k-card-top-row">
            <span class="k-card-tag tag-sage">4. Практика</span>
            <span class="k-ratio-chip">Грай і слухай</span>
          </div>
          <h4>4 дієві способи тренуватися з Колом</h4>
        </div>
        <span class="k-accordion-chevron" aria-hidden="true">⌄</span>
      </summary>
      <div class="k-accordion-body">
        <ul class="k-physics-list">
          <li><strong>Вийди за межі «лише C і G»:</strong> Візьми будь-який новий риф, гаму або каданс і рухайся щодня на один сектор за стрілкою (<code>C → G → D → A</code>) або проти стрілки крізь духові бемолі (<code>F → B♭ → E♭ → A♭</code>). За 12 днів опануєш весь гриф або клавіатуру.</li>
          <li><strong>Слухай секвенції по колу (<code>vi–ii–V–I</code>):</strong> Рахуй назад до 12 години: кожен акорд стає маленькою домінантою, що тягне в наступний сектор! Натисни нижче, щоб відчути цю гравітацію в до мажорі.</li>
          <li><strong>Позичай сусідню барву (побічні домінанти):</strong> Граючи в C і бажаючи яскравішого підйому перед <code>G (V)</code>, загляни на крок за стрілкою по <code>F♯</code> і перетвори мінорний <code>ii (Dm)</code> на сяючий <strong>D7 (V/V)</strong> просто в G!</li>
          <li><strong>Контраст теплих і яскравих зсувів:</strong> Крок ліворуч (<code>I → IV → bVII</code>) дає теплий, соуловий, розслаблений ґрув; крок праворуч (<code>I → V → V/V</code>) заряджає драйвом і світлом.</li>
        </ul>
        <div class="k-btn-row">
          <button class="btn-tool" data-play-progression="vi,ii,V7,I">▶ Тяжіння колом (Am–Dm–G7–C)</button>
          <button class="btn-tool" data-play-progression="I,V/V,V,I">▶ Підйом за стрілкою (C–D (V/V)–G–C)</button>
        </div>
      </div>
    </details>
  `;
}

function getIntervalNamingGuideHTML_UK() {
  const isDeNotation = typeof state !== "undefined" ? state?.profile?.intervalNotation !== "intl" : false;
  const sym = typeof formatIntervalSymbol === "function" ? formatIntervalSymbol : k => k;
  const activeLabel = isDeNotation ? "Німецька (P / G / k)" : "Міжнародна (P / M / m)";
  return `
    <details class="knowledge-card k-accordion" id="intervalNamingGuideAccordion" open>
      <summary class="k-accordion-summary">
        <div class="k-accordion-head">
          <div class="k-card-top-row">
            <span class="k-card-tag tag-sage">Назви й скорочення</span>
            <span class="k-ratio-chip">Активно: ${activeLabel}</span>
          </div>
          <h4>Як працюють позначення інтервалів (Літера + Цифра)</h4>
        </div>
        <span class="k-accordion-chevron" aria-hidden="true">⌄</span>
      </summary>
      <div class="k-accordion-body">
        <p>Кожне коротке позначення кодує два факти у двох знаках: <strong>цифра</strong> рахує кількість ступенів від основної ноти, а <strong>літера перед нею</strong> уточнює точну ширину в півтонах.</p>
        <ul class="k-physics-list">
          <li><strong>1. Цифра (<code>1</code>–<code>9</code>) рахує ступені гами:</strong> Від <code>1</code> = Прима (той самий тон), <code>2</code> = Секунда, <code>3</code> = Терція, <code>4</code> = Кварта, <code>5</code> = Квінта, <code>6</code> = Секста, <code>7</code> = Септима, <code>8</code> = Октава до <code>9</code> = Нона.</li>
          <li><strong>2. Чисті інтервали (<code>P</code> = <em>Perfect</em>):</strong> <code>P1</code>, <code>P4</code>, <code>P5</code> та <code>P8</code> існують в одному чистому вигляді — без поділу на великий чи малий, у максимально відкритих пропорціях.</li>
          <li><strong>3. Великі та малі пари (<code>2</code>, <code>3</code>, <code>6</code>, <code>7</code>, <code>9</code>):</strong> Кожен із цих п’яти інтервалів має два варіанти з різницею в <strong>1 півтон</strong>:<br>
            – <strong>Міжнародна (<code>P / M / m</code>):</strong> велика <strong><code>M</code></strong> (<em>Major</em>) позначає ширший, світліший інтервал; мала <strong><code>m</code></strong> (<em>minor</em>) на 1 півтон вужча (напр., <code>M3</code> проти <code>m3</code>). Тут велика чи мала літера вирішує все!<br>
            – <strong>Німецька (<code>P / G / k</code>):</strong> велика <strong><code>G</code></strong> (<em>Groß</em> = великий) проти малої <strong><code>k</code></strong> (<em>klein</em> = малий, напр., <code>G3</code> проти <code>k3</code>).</li>
          <li><strong>4. Тритон (<code>TT</code>):</strong> Ділить октаву точно навпіл на <strong>6 півтонів</strong> між <code>P4</code> та <code>P5</code> (збільшена кварта / зменшена квінта).</li>
        </ul>
        <div class="k-meta-box">
          <div><strong>Активні скорочення:</strong> Секунди: <code>${sym("m2")}</code> (1 пт) проти <code>${sym("M2")}</code> (2 пт) · Терції: <code>${sym("m3")}</code> (3 пт) проти <code>${sym("M3")}</code> (4 пт)</div>
          <div><strong>Перемикач:</strong> У <strong>Налаштуваннях → Мова та нотація → Музична нотація → Назви інтервалів</strong> будь-коли перемикайся між <strong>Міжнародними (P / M / m)</strong> та <strong>Німецькими (P / G / k)</strong>.</div>
        </div>
      </div>
    </details>
  `;
}

