function renderNotationReferenceHTML_UK() {
  const staffFn = typeof buildNotationKnowledgeStaffSVG === "function" ? buildNotationKnowledgeStaffSVG : null;
  const trebleAnchorSvg = staffFn ? staffFn("treble", [0, 2, 4, 6, 8], { width: 290, highlightAnchorLine: true, showLabels: true, labelShort: true }) : "";
  const bassAnchorSvg = staffFn ? staffFn("bass", [0, 2, 4, 6, 8], { width: 290, highlightAnchorLine: true, showLabels: true, labelShort: true }) : "";
  const altoAnchorSvg = staffFn ? staffFn("alto", [0, 2, 4, 6, 8], { width: 290, highlightAnchorLine: true, showLabels: true, labelShort: true }) : "";
  const ledgerSvg = staffFn ? staffFn("treble", [-6, -4, -2, 4, 10, 12, 14], { width: 340, showLabels: true, labelShort: true }) : "";
  const ledgerBassSvg = staffFn ? staffFn("bass", [-6, -4, -2, 4, 10, 12, 14], { width: 340, showLabels: true, labelShort: true }) : "";
  const accSvg = staffFn ? staffFn("treble", [
    { step: 1, accidental: 0 },
    { step: 1, accidental: 1 },
    { step: 2, accidental: -1 },
    { step: 6, accidental: 0 },
    { step: 6, accidental: -1 }
  ], { width: 320, showLabels: true, labelShort: true }) : "";
  const keySigSharpSvg = staffFn ? staffFn("treble", [
    { step: 1, accidental: 1 },
    { step: 5, accidental: 1 },
    { step: 1, accidental: 0 }
  ], { width: 300, keySignatureId: "D", showLabels: true, labelShort: true }) : "";
  const keySigFlatSvg = staffFn ? staffFn("treble", [
    { step: 4, accidental: -1 },
    { step: 7, accidental: -1 },
    { step: 2, accidental: 0 }
  ], { width: 300, keySignatureId: "Eb", showLabels: true, labelShort: true }) : "";

  return `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">1. П’ятилінійний нотний стан</span>
        <span class="k-ratio-chip">Лінійки й проміжки</span>
      </div>
      <h4>Як музика перетворюється на координати</h4>
      <p>
        Нотний запис працює як точний графік: <strong>вертикальна вісь</strong> задає висоту звука (вище = вищий тон, нижче = басовитіший), а <strong>горизонтальна вісь</strong> рухає час зліва направо.
      </p>
      <ul class="k-physics-list">
        <li><strong>Завжди рахуй знизу вгору:</strong> Нотний стан має <strong>5 лінійок</strong> (1-ша внизу, 5-та вгорі) та <strong>4 проміжки</strong> між ними.</li>
        <li><strong>Чергування «лінійка – проміжок»:</strong> Перехід із лінійки на сусідній проміжок (чи навпаки) завжди дорівнює рівно <strong>одному діатонічному кроку</strong> (<code>C → D → E → F → G → A → B</code>).</li>
        <li><strong>Навіщо потрібен ключ:</strong> Без ключа лінійки безіменні — саме ключ закріплює <em>один точний орієнтир</em> на певній лінійці.</li>
      </ul>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">2. 3 головні ключі (і спецключі)</span>
        <span class="k-ratio-chip">Скрипковий • Басовий • Альтовий</span>
      </div>
      <h4>Три погляди на ту саму клавіатуру</h4>
      <p>
        Помаранчева лінійка підсвічує <strong>опорну ноту</strong> кожного ключа. Варто запам’ятати цей один маяк, щоб миттєво зчитувати сусідні ступені.
      </p>
      <div class="notation-knowledge-grid">
        <div class="notation-knowledge-card">
          ${trebleAnchorSvg}
          <h5>Скрипковий ключ (ключ Соль)</h5>
          <p>Завиток центру охоплює <strong>2-гу лінійку знизу = Соль першої октави (G4)</strong>. Стандарт для вокалу (сопрано/альт), скрипки, флейти, труби, гітари й правої руки фортепіано.</p>
          <p><strong>Орієнтири (знизу → вгору):</strong> лінійки <em>Мі – Соль – Сі – Ре – Фа</em>; проміжки <em>Фа – Ля – До – Мі</em> (FACE).</p>
          <button type="button" class="btn-tool" data-play-solo-note="G4">▶ Почути орієнтир G4</button>
        </div>
        <div class="notation-knowledge-card">
          ${bassAnchorSvg}
          <h5>Басовий ключ (ключ Фа)</h5>
          <p>Дві крапки обрамлюють <strong>4-ту лінійку знизу = Фа малої октави (F3)</strong>. Основа для лівої руки фортепіано, віолончелі, контрабаса, бас-гітари, тромбона, фагота й чоловічих басів.</p>
          <p><strong>Орієнтири (знизу → вгору):</strong> лінійки <em>Соль – Сі – Ре – Фа – Ля</em>; проміжки <em>Ля – До – Мі – Соль</em>.</p>
          <button type="button" class="btn-tool" data-play-solo-note="F3">▶ Почути орієнтир F3</button>
        </div>
        <div class="notation-knowledge-card">
          ${altoAnchorSvg}
          <h5>Альтовий ключ (ключ До на 3-й лінійці)</h5>
          <p>Центр знака вказує точно на <strong>3-тю (середню) лінійку = До першої октави (C4)</strong>. Основний ключ альта в оркестрі та класичної хорової поліфонії.</p>
          <p><strong>Симетрія ключа До:</strong> Оскільки <code>C4</code> стоїть точно посередині, угору на 4-й і 5-й лінійках лежать <em>Мі</em> та <em>Соль</em>, а вниз на 2-й і 1-й — <em>Ля</em> та <em>Фа</em>.</p>
          <button type="button" class="btn-tool" data-play-solo-note="C4">▶ Почути орієнтир C4</button>
        </div>
      </div>

      <div class="k-meta-box">
        <div><strong>Та сама середня До (C4) з’єднує всі три ключі:</strong> у <strong>скрипковому</strong> вона лежить на 1-й додатковій лінійці <em>знизу</em>, в <strong>альтовому</strong> — точно в <em>центрі (3-тя лінійка)</em>, а в <strong>басовому</strong> — на 1-й додатковій лінійці <em>зверху</em>!</div>
        <div><strong>Спеціальні ключі (огляд):</strong> <strong>Теноровий ключ</strong> піднімає той самий ключ До на 4-ту лінійку (для високих партій віолончелі, фагота чи тромбона), а октавні ключі (<code>8vb</code> / <code>8va</code>) зміщують нотацію гітари чи флейти-піколо без зайвих додаткових лінійок.</div>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">3. До 3 додаткових лінійок</span>
        <span class="k-ratio-chip">±3 додаткові лінійки</span>
      </div>
      <h4>Читаємо високо й низько без повільного перерахунку</h4>
      <p>
        Коли мелодія піднімається вище 5-ї або спускається нижче 1-ї лінійки, тільки під цією нотою малюють короткі <strong>додаткові лінійки</strong>. У тренажері охоплено до <strong>3 додаткових лінійок в обидва боки</strong> — саме той обсяг, що щодня трапляється в нотах для ансамблю й фортепіано.
      </p>
      <div class="notation-knowledge-grid">
        <div class="notation-knowledge-card">
          ${ledgerSvg}
          <h5>Скрипковий ключ: ±3 додаткові лінійки</h5>
          <p>Ліворуч: 3-тя, 2-га і 1-ша лінійки знизу (<code>F3 – A3 – C4</code>); у центрі: <code>B4</code>; праворуч: 1-ша, 2-га і 3-тя лінійки зверху (<code>A5 – C6 – E6</code>).</p>
        </div>
        <div class="notation-knowledge-card">
          ${ledgerBassSvg}
          <h5>Басовий ключ: глибокий бас і верхній регістр</h5>
          <p>Униз 3 лінійки сягають через <code>E2 – C2</code> до субконтр/контр-Ля (<code>A1</code>), а вгору через середню <code>C4</code> відкривають <code>E4</code> і <code>G4</code>.</p>
        </div>
      </div>
      <ul class="k-physics-list">
        <li><strong>Запам’ятай по 2 «буйки» за межами стану:</strong> Зафіксуй 1-шу та 2-гу додаткову лінійку (напр., <code>C4</code> і <code>A3</code> під скрипковим або <code>A5</code> і <code>C6</code> над ним) та зчитуй сусідів у проміжках миттєво.</li>
        <li><strong>Бач кроки через лінійку:</strong> Стрибок із додаткової лінійки на наступну додаткову лінійку завжди дорівнює <strong>терції</strong> — так само, як будуються тризвуки!</li>
      </ul>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">4. Знаки альтерації та нотації</span>
        <span class="k-ratio-chip">♯ • ♭ • B vs H</span>
      </div>
      <h4>Чорні клавіші, енгармонізм і німецька система H / B</h4>
      <div class="notation-knowledge-grid">
        <div class="notation-knowledge-card">
          ${accSvg}
          <div class="k-btn-row" style="margin-top:0.25rem;">
            <button type="button" class="btn-tool" data-play-solo-note="F4">▶ F4</button>
            <button type="button" class="btn-tool" data-play-solo-note="F#4">▶ F♯4 / G♭4</button>
            <button type="button" class="btn-tool" data-play-solo-note="Bb4">▶ B♭4</button>
          </div>
        </div>
        <div class="notation-knowledge-card">
          <ul class="k-physics-list">
            <li><strong>Дієз (<code>♯</code>):</strong> Підвищує ноту рівно на <strong>1 півтон</strong> (на сусідню клавішу праворуч). Із <code>F</code> утворюється <code>F♯</code>.</li>
            <li><strong>Бемоль (<code>♭</code>):</strong> Знижує ноту рівно на <strong>1 півтон</strong> (ліворуч). Із <code>G</code> утворюється <code>G♭</code>.</li>
            <li><strong>Енгармонійна рівність:</strong> На клавіатурі <code>F♯</code> і <code>G♭</code> — та сама фізична клавіша, але в нотах написання показує гармонічну функцію.</li>
            <li><strong>Німецька vs міжнародна нотація:</strong> У німецькій традиції чиста біла нота <em>Сі (B)</em> позначається літерою <strong>H</strong>, а <em>Сі-бемоль (B♭)</em> — літерою <strong>B</strong>! Обидва варіанти можна перемикати в <em>Налаштуваннях застосунку</em>.</li>
          </ul>
        </div>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">5. Тональності та ключові знаки</span>
        <span class="k-ratio-chip">Читання з ♮</span>
      </div>
      <h4>Коли знаки альтерації діють на весь нотний стан</h4>
      <p>
        Замість того щоб ставити <code>♯</code> чи <code>♭</code> перед кожною нотою, ключові знаки стоять <strong>одразу після ключа</strong> і автоматично змінюють відповідні ступені у <strong>всіх октавах</strong>, доки їх не скасує бекар (<code>♮</code>).
      </p>
      <div class="notation-knowledge-grid">
        <div class="notation-knowledge-card">
          ${keySigSharpSvg}
          <h5>Дієзні тональності (Порядок: Фа – До – Соль – Ре – Ля – Мі)</h5>
          <p>У <strong>Ре мажорі (2♯)</strong> кожна <code>Fa</code> стає <code>F♯</code>, а <code>Do</code> стає <code>C♯</code> — і лише бекар (<code>♮</code>) перед третьою нотою повертає білу <code>F</code>.</p>
        </div>
        <div class="notation-knowledge-card">
          ${keySigFlatSvg}
          <h5>Бемольні тональності (Порядок: Сі – Мі – Ля – Ре – Соль – До)</h5>
          <p>У <strong>Мі♭ мажорі (3♭)</strong> знаки <code>B♭</code>, <code>E♭</code> і <code>A♭</code> діють від самого початку стану, доки не з’явиться знак відміни <code>♮</code>.</p>
        </div>
      </div>
    </article>
  `;
}

function renderArrangingReferenceHTML_UK() {
  return `
    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">1. Що таке аранжування?</span>
        <span class="k-ratio-chip">Ескіз → Повне звучання</span>
      </div>
      <h4>Мистецтво перетворювати музичну ідею на живий звуковий простір</h4>
      <p>
        Якщо <strong>композиція</strong> — це креслення пісні (мелодія, базові акорди й текст), то <strong>аранжування</strong> — це вся архітектура, освітлення та палітра барв: <em>Хто, що й коли грає, у якій октаві, з яким ритмом, динамікою та тембром?</em>
      </p>
      <div class="physics-fact-grid">
        <div class="physics-fact-item">
          <strong>Інструментовка й тембри</strong>
          Вибір інструментів або голосів для мелодії, баса, гармонічної подушки й ритму та поєднання їхніх барв.
        </div>
        <div class="physics-fact-item">
          <strong>Форма і драматургія</strong>
          Побудова емоційної дуги від камерного вступу через куплет до кульмінації у приспіві та фіналу.
        </div>
        <div class="physics-fact-item">
          <strong>Регістри й войсинг</strong>
          Розподіл нот від глибокого баса до прозорих верхів, щоб кожен інструмент мав власний простір без гудіння.
        </div>
        <div class="physics-fact-item">
          <strong>Діалог, фактура і паузи</strong>
          Коли звучать усі разом (<em>tutti</em>), коли один інструмент відповідає в паузах вокалу, а коли тиша викликає мурашки.
        </div>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">2. Призначення та сфери застосування</span>
        <span class="k-ratio-chip">Навіщо аранжувати?</span>
      </div>
      <h4>Для чого потрібне аранжування і де воно використовується?</h4>
      <p>
        Одна й та сама пісня з тими самими чотирма акордами може прозвучати як <strong>ніжна фортепіанна балада</strong>, <strong>драйвовий фанк</strong>, <strong>чотириголосний хор a cappella</strong> або <strong>епічний саундтрек</strong>:
      </p>
      <ul class="article-steps-list">
        <li><strong>1. Керування увагою слухача:</strong> Вухо людини свідомо відстежує щонайбільше <strong>2–3 одночасні музичні плани</strong>. Гарне аранжування звільняє середній регістр для головної мелодії чи голосу.</li>
        <li><strong>2. Передача емоцій і стилю:</strong> Струнні педи дають тепло й простір, короткі духові акценти (<em>brass stabs</em>) — енергію, а акустична гітара — камерну близькість.</li>
        <li><strong>3. Захист від втоми вуха:</strong> Якщо всі інструменти грають без зупинки з першого такту, слух швидко втомлюється. Пошарове додавання і зняття партій тримає інтерес до останньої ноти.</li>
        <li><strong>4. Адаптація під реальний склад:</strong> Шкільний гурт, струнний квартет, хор SATB, біг-бенд чи соло-фортепіано — аранжування підлаштовує твір під конкретних виконавців та їхні діапазони.</li>
        <li><strong>5. Музичний «клей» і переходи:</strong> Затакти, барабанні брейки, басові ходи та наростання органічно з’єднують частини пісні.</li>
      </ul>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">3. Модель 4 шарів</span>
        <span class="k-ratio-chip">Розподіл ролей</span>
      </div>
      <h4>4 будівельні блоки прозорого аранжування</h4>
      <ul class="k-physics-list">
        <li><strong>1. Передній план (Lead / Мелодія):</strong> Вокал або сольний інструмент, що веде головну лінію.</li>
        <li><strong>2. Фундамент (Бас і Грув):</strong> Бас задає основний тон гармонії, а ударні тримають ритмічну пульсацію.</li>
        <li><strong>3. Гармонічна подушка (Pad &amp; Comping):</strong> Струнні, хор, орган або ритмічний акомпанемент гітари/клавішних у середині спектра.</li>
        <li><strong>4. Контрапункт і підголоски (Fills / Ear Candy):</strong> Короткі мелодійні відповіді саме там, де головна мелодія бере подих.</li>
      </ul>
      <div class="k-btn-row" style="margin-top:0.5rem;">
        <button type="button" class="btn-tool" data-play-custom="arr-sketch">▶ 1. Простий ескіз (лише мелодія і бас)</button>
        <button type="button" class="btn-tool" data-play-custom="arr-full-layers">▶ 2. Повне 4-шарове аранжування</button>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-sage">4. Регістри та войсинг</span>
        <span class="k-ratio-chip">Прозорість замість каші</span>
      </div>
      <h4>Чому одні аранжування звучать кришталево чисто, а інші — «кашоподібно»</h4>
      <ul class="k-physics-list">
        <li><strong>Правило обертонів (Унизу широко, угорі щільно):</strong> Нижче <code>C3</code> тісні терції звучать глухо й важко (<em>Low-Interval Limit</em>). Залишайте в басу основні тони, квінти й октави, а терції, септими й надбудови розміщуйте вище.</li>
        <li><strong>Тісне vs широке розташування (Drop-2):</strong> Перенесення другого зверху звука акорду на октаву вниз миттєво відкриває широкий кінематографічний простір.</li>
        <li><strong>Ритмічний розподіл:</strong> Інструменти в сусідніх регістрах мають доповнювати один одного ритмічно (довгі педи + короткі шістнадцяті).</li>
      </ul>
      <div class="k-btn-row" style="margin-top:0.5rem;">
        <button type="button" class="btn-tool" data-play-custom="arr-voicing-muddy">▶ Каша: Тісні терції низько в басу</button>
        <button type="button" class="btn-tool" data-play-custom="arr-voicing-open">▶ Чисто: Відкритий студійний войсинг</button>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-peach">5. Динаміка і діалог</span>
        <span class="k-ratio-chip">Call &amp; Response • Drop</span>
      </div>
      <h4>Як втримати увагу слухача протягом усього твору</h4>
      <ul class="article-steps-list">
        <li><strong>Call &amp; Response (Поклик і відповідь):</strong> Інструмент відповідає у паузі після вокальної фрази.</li>
        <li><strong>Протилежний рух і контрамелодія:</strong> Другий голос рухається назустріч мелодії або оживає, поки мелодія тримає довгу ноту.</li>
        <li><strong>Сила віднімання («The Drop»):</strong> Раптове розрідження фактури на один-два такти часто створює сильніший ефект, ніж додавання нових доріжок.</li>
      </ul>
      <div class="k-btn-row" style="margin-top:0.5rem;">
        <button type="button" class="btn-tool" data-play-custom="arr-call-response">▶ Call &amp; Response (діалог у паузі)</button>
        <button type="button" class="btn-tool" data-play-custom="arr-counterpoint">▶ Контрапункт у протилежному русі</button>
      </div>
    </article>

    <article class="knowledge-card">
      <div class="k-card-top-row">
        <span class="k-card-tag tag-lilac">6. Регармонізація та чек-лист</span>
        <span class="k-ratio-chip">Ті самі ноти, нове світло</span>
      </div>
      <h4>Та сама мелодія в абсолютно новому гармонічному вбранні</h4>
      <p>
        <strong>Регармонізація</strong> залишає мелодію незмінною, але оновлює акорди під нею (наприклад, <code>Fmaj7 – Fm6 – Am9</code> замість простого <code>C – G – C</code>).
      </p>
      <div class="k-btn-row" style="margin-top:0.45rem;margin-bottom:0.65rem;">
        <button type="button" class="btn-tool" data-play-custom="arr-reharm-plain">▶ Мелодія на простих тризвуках (I–V–I)</button>
        <button type="button" class="btn-tool" data-play-custom="arr-reharm-cinema">▶ Та сама мелодія з кінематографічною гармонією</button>
      </div>
      <div class="k-meta-box">
        <div><strong>5 контрольних запитань для власного аранжування:</strong></div>
        <div>1. <strong>Хто зараз головний?</strong> У кожен момент часу лише один елемент має бути у центрі уваги.</div>
        <div>2. <strong>Де місця для подиху?</strong> Розміщуйте підголоски в паузах головної мелодії.</div>
        <div>3. <strong>Чи чистий низький регістр?</strong> Уникайте тісних терцій нижче <code>C3</code>.</div>
        <div>4. <strong>Чи відчувається контраст між куплетом і приспівом?</strong> Змінюйте ширину регістру та щільність ритму.</div>
        <div>5. <strong>Тест кнопки Mute:</strong> Якщо після вимкнення доріжки пісня нічого не втратила — дайте їй чітку роль або сміливо приберіть!</div>
      </div>
      <div class="k-btn-row" style="margin-top:0.55rem;">
        <button type="button" class="btn-tool" data-jump-ref="ensembles">До Оркестрів і Гуртів →</button>
        <button type="button" class="btn-tool" data-jump-ref="cadences">До Каденцій і Гармонії →</button>
        <button type="button" class="btn-tool" data-jump-ref="physics">До Фізики й Обертонів →</button>
      </div>
    </article>
  `;
}

if (typeof registerKnowledgeBundle === "function") {
  registerKnowledgeBundle("uk", {
    data: {
      intervalEncyclopedia: INTERVAL_ENCYCLOPEDIA_UK,
      cadenceEncyclopedia: CADENCE_ENCYCLOPEDIA_UK,
      solfegeSteps: SOLFEGE_STEPS_UK,
      knowledgeArticles: KNOWLEDGE_ARTICLES_UK,
      physicsWaveExplanations: PHYSICS_WAVE_EXPLANATIONS_UK,
      physicsOvertones: PHYSICS_OVERTONES_UK,
      categoryHelpGuides: CATEGORY_HELP_GUIDES_UK,
      rhythmInstruments: RHYTHM_INSTRUMENTS_DATA_UK,
      instrumentModules: INSTRUMENT_MODULES_UK,
      modesEncyclopedia: MODES_ENCYCLOPEDIA_UK,
      keysCircleData: KEYS_CIRCLE_DATA_UK
    },
    renderers: {
      physics: renderPhysicsReferenceHTML_UK,
      rhythm: renderRhythmReferenceHTML_UK,
      rhythmInstruments: renderRhythmInstrumentsHTML_UK,
      vocals: renderVocalsReferenceHTML_UK,
      instrumentModule: renderInstrumentModuleHTML_UK,
      modes: renderModesReferenceHTML_UK,
      keys: renderKeysReferenceHTML_UK,
      singAndPlay: renderSingAndPlayReferenceHTML_UK,
      notation: renderNotationReferenceHTML_UK,
      arranging: renderArrangingReferenceHTML_UK,
      intervalNamingGuide: getIntervalNamingGuideHTML_UK,
      circleOfFifthsTheory: renderCircleOfFifthsTheoryHTML_UK
    },
    circleData: CIRCLE_OF_FIFTHS_UK_DATA,
    circleRoles: CIRCLE_ROLES_UK
  });
}
